let dbPromise;
function db(){return dbPromise ||=new Promise((resolve,reject)=>{const r=indexedDB.open('ATMyTrack',1);r.onupgradeneeded=()=>{r.result.createObjectStore('projects',{keyPath:'id'});r.result.createObjectStore('audio');};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function transaction(store,mode,action){const d=await db();return new Promise((resolve,reject)=>{const tx=d.transaction(store,mode),r=action(tx.objectStore(store));tx.oncomplete=()=>resolve(r?.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('Armazenamento indisponível'));});}
export const allProjects=()=>transaction('projects','readonly',s=>s.getAll());
export const saveProject=p=>transaction('projects','readwrite',s=>s.put(structuredClone(p)));
export const deleteProject=p=>Promise.all([transaction('projects','readwrite',s=>s.delete(p.id)),...p.tracks.map(t=>transaction('audio','readwrite',s=>s.delete(t.id)))]);
export const putAudio=(id,blob)=>transaction('audio','readwrite',s=>s.put(blob,id));
export const getAudio=id=>transaction('audio','readonly',s=>s.get(id));
export function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
export async function exportProject(p){const audio={};for(const t of p.tracks){const b=await getAudio(t.id);if(!b)throw Error('Áudio ausente: '+t.name);audio[t.id]=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(b);});}download(new Blob([JSON.stringify({format:'ATMyTrack-Web',version:1,project:p,audio})],{type:'application/json'}),p.name+'.atmytrack');}
export async function importBackup(file){const x=JSON.parse(await file.text());if(x.format!=='ATMyTrack-Web'||x.version!==1||!Array.isArray(x.project?.tracks)||!x.audio)throw Error('Backup inválido. Use um arquivo exportado pela versão web.');const p=x.project;p.id=crypto.randomUUID();const map=new Map();for(const t of p.tracks){const old=t.id,raw=x.audio[old];if(typeof raw!=='string'||!raw.startsWith('data:')||!raw.includes(';base64,'))throw Error('Backup com áudio inválido.');const bytes=Uint8Array.from(atob(raw.split(',')[1]),c=>c.charCodeAt(0));t.id=crypto.randomUUID();map.set(old,t.id);await putAudio(t.id,new Blob([bytes]));}p.pitchTracks=p.pitchTracks?.map(x=>map.get(x)).filter(Boolean);p.speedTracks=p.speedTracks?.map(x=>map.get(x)).filter(Boolean);for(const d of p.dcas||[])d.members=d.members.map(x=>map.get(x)).filter(Boolean);await saveProject(p);return p;}
